import{z as o,x as n,o as E,c as A,q as t,j as i,D as e,d as B,s,S as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"限流与熔断","description":"","frontmatter":{"title":"限流与熔断","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rate-limit-circuit-breaker.md","filePath":"cs/rate-limit-circuit-breaker.md","lastUpdated":1791063341000}'),p={name:"cs/rate-limit-circuit-breaker.md"};function d(C,a,c,_,m,h){const r=n("Mermaid");return E(),A("div",null,[a[2]||(a[2]=t('<h1 id="限流与熔断" tabindex="-1">限流与熔断 <a class="header-anchor" href="#限流与熔断" aria-label="Permalink to &quot;限流与熔断&quot;">​</a></h1><div class="epigraph"><p>限流挡住过量好请求；熔断在下游已病时拒绝新请求，避免重试把病机打死。二者都是负载的负反馈，不是业务正确性。</p><footer>—— 据 Netflix Hystrix 设计；token bucket / leaky bucket 经典控制；Dean 对过载的讨论整理</footer></div><p>上一课<a href="/cs/cache-stampede-hotkey">雪崩与热键</a>仍可能打穿。缺口是<strong>保护面</strong>：即使单飞，总量仍可超过存储。本课钉限流与熔断，不重写填充租约。后课超时退避说明熔断打开期间重试如何把闭环做坏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>限流：令牌桶、漏桶、滑动窗口，按键、用户、分片配额。超限快速失败，保护的是被调用者。熔断：统计错误率或延迟，打开后短时间短路，半开探测。Nygard 的《Release It!》把熔断当稳定模式；Hystrix 做成库。</p><p>缺口：限流在调用方还是网关。只在一端，另一端仍可被别的客户端打满。熔断若按错误率，下游限流返回的 429 会被当成故障而打开——策略要区分过载与真故障。</p><p><span class="marginnote">令牌桶允许短突发；漏桶平滑。选哪一种是产品对突发的态度，不是定理。</span></p><p><span class="marginnote">数字实例：令牌桶设速率 \\(r=10\\) 个/秒、桶容量 \\(B=100\\)。空闲一分钟攒满 100 个令牌后，下一秒可以瞬间放行 100 个请求（突发），随后回落到每秒 10 个。换成同样速率的漏桶，这 100 个请求会被摊成约 10 秒的匀速流。突发容忍度就是这两种桶的本质差别。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层：边缘限流（用户）+ 服务间限流（依赖配额）+ 熔断（依赖健康）。配额要按分片，避免热用户占满全局桶。熔断窗口与半开探测并发数要小，防探测雪崩。</p>',10)),(E(),i(l,null,{default:e(()=>[s(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20RL%7B%22%E9%99%90%E6%B5%81%E9%80%9A%E8%BF%87%3F%22%7D%0A%20%20RL%20--%3E%7C%22%E5%90%A6%22%7C%20REJ%5B%22%E5%BF%AB%E9%80%9F%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20RL%20--%3E%7C%22%E6%98%AF%22%7C%20CB%7B%22%E7%86%94%E6%96%AD%E5%85%B3%E9%97%AD%3F%22%7D%0A%20%20CB%20--%3E%7C%22%E5%BC%80%22%7C%20FAIL%5B%22%E7%9F%AD%E8%B7%AF%22%5D%0A%20%20CB%20--%3E%7C%22%E5%85%B3%22%7C%20DOWN%5B%22%E4%B8%8B%E6%B8%B8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>不要用熔断替代<a href="/cs/timeout-backoff">超时</a>：无限等会让错误率统计失真。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>过载崩溃：队列满、GC、线程池耗尽。熔断把失败从「超时 30s」变成「立即」，释放调用方资源。这与<a href="/cs/tail-latency-hedging">尾延迟</a>相关：长尾占满池子。限流是主动掉请求保平均数；熔断是下游已掉时停止喂食。</p><p><span class="marginnote">为什么重要：假设下游真挂了，每个请求都要等 30 秒超时。1000 QPS 的流量、每请求占一个工作线程，30 秒内就压着 3 万个线程在干等——还没轮到下游救活，调用方自己先被线程池拖死。熔断把这 30 秒换成微秒级的立即失败，等于给调用方止血。</span></p><p><span class="marginnote">常见误区：初学者容易把下游限流返回的 429 也计进熔断的错误率。429 表示「下游活着，只是让排队」，把当成故障会让熔断打开、探测请求又被限流拒绝、熔断永远打不开回不来。正确做法是 429 与 5xx 分开计数，只有真故障才推动状态机。</span></p>',5)),(E(),i(l,null,{default:e(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%85%B3%E9%97%AD%EF%BC%9A%E6%AD%A3%E5%B8%B8%E6%94%BE%E8%A1%8C%EF%BC%8C%E6%BB%9A%E5%8A%A8%E7%BB%9F%E8%AE%A1%E9%94%99%E8%AF%AF%E7%8E%87%22%5D%20--%3E%7C%22%E9%94%99%E8%AF%AF%E7%8E%87%E8%B6%85%E8%BF%87%E9%98%88%E5%80%BC%22%7C%20O%5B%22%E6%89%93%E5%BC%80%EF%BC%9A%E7%AB%8B%E5%8D%B3%E7%9F%AD%E8%B7%AF%EF%BC%8C%E4%B8%8D%E7%A2%B0%E4%B8%8B%E6%B8%B8%22%5D%0A%20%20O%20--%3E%7C%22%E5%86%B7%E5%8D%B4%E6%97%B6%E9%97%B4%E5%88%B0%22%7C%20H%5B%22%E5%8D%8A%E5%BC%80%EF%BC%9A%E5%8F%AA%E6%94%BE%E5%B0%91%E9%87%8F%E6%8E%A2%E6%B5%8B%E8%AF%B7%E6%B1%82%22%5D%0A%20%20H%20--%3E%7C%22%E6%8E%A2%E6%B5%8B%E6%88%90%E5%8A%9F%EF%BC%8C%E6%81%A2%E5%A4%8D%E7%BB%9F%E8%AE%A1%22%7C%20C%0A%20%20H%20--%3E%7C%22%E6%8E%A2%E6%B5%8B%E4%BB%8D%E5%A4%B1%E8%B4%A5%22%7C%20O%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>分布式限流：中心计数器是热点；本地近似桶会超卖。超卖多少要进规格。本课不把 Redis INCR 当完备分布式桶证明。</p><p>本课不写 HTTP 429 的全部头。也不写电力断路器物理课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把自适应并发控制（TCP Vegas、CoDel、adaptive LIFO）写全，点名即可。后课默认：依赖调用有配额与熔断；429 与 5xx 分开计数。超时退避下一课处理「失败后何时再试」，否则熔断永远被重试撬开。</p><p>保险丝保护的是系统，不是这次用户请求的恰好一次。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>限流：配额内才放行；熔断：下游病则短路。</li><li>429 与故障要分开，以免误打开。</li><li>桶可超卖若只在本地近似。</li><li>出处：Hystrix；令牌桶；Nygard 稳定模式。</li></ul>',7))])}const F=o(p,[["render",d]]);export{D as __pageData,F as default};
